local GrowthFundDialog = Class("GrowthFundDialog")
function GrowthFundDialog:__init()
    self.rewardVo = {}
    self.rewardList = {}
    self.rewardDojo = {}
    self.purchaseData = {}--领取状态的服务器数据
    self.playerLevel = nil --玩家等级
    self.isPurchased = nil--购买了月卡
    self.purchasedEffectGo = nil--list的购买特效
    self:ResetAnimData()


end

function GrowthFundDialog:__delete()
    self.controller = nil
    self.rewardVo = nil
    self.rewardList = nil
    self.rewardDojo = nil
    self.purchaseData = nil
    self.playerLevel = nil
    self.isPurchased = nil
    for i = 1, LoopViewMaxCellCount do
        self["isAnimated"..i] = nil
    end


end

function GrowthFundDialog:Awake()
    --self.controller.IsAutoHandleNavBar = false

end

function GrowthFundDialog:OnFocus(focus)
    if focus then
        GameUtils.UpdateNavBarShowState(false, false)
    end
end

function GrowthFundDialog:ResetAnimData()
    for i = 1, LoopViewMaxCellCount do
        self["isAnimated"..i] = false
    end
end

function GrowthFundDialog:RefreshSelf()
    self.rewardVo = CfUtils.GetWholeVo(AutoIds.IdSetting980,"GrowthFundRewardVo")--获得成长基金奖励表
    self.purchaseData = CfUtils.GetCfVo(AutoIds.IdSetting981, "GrowthFundPurchaseVo", 1)
    self.playerLevel = playerComponent.playerDojo.level
    GameUtils.Request(
            Interfaces.GrowthFundHome,
            {  },
            function(request, response)
                if checkInt(response.errCode) == 0 then
                    self.rewardDojo = response.data.growthFundInfo
                    playerComponent.playerDojo.paidPayLevelRewards = response.data.paidPayLevelRewards
                    playerComponent.playerDojo.freePayLevelRewards = response.data.freePayLevelRewards
                    playerComponent.playerDojo.isBuyGrowthFund = response.data.isBuyGrowthFund
                    self:FreshBaseUI()
                end
            end
    )
end

