function GrowthFundDialog:FreshBaseUI()
    self:SortRewardData()
    local currencyVo = GoodsConfMgr:GetInstance():GetGoodsVoById(self.purchaseData.goodsConsum)
    CfUtils.FillText(self.TxtCurrencyNum, self.purchaseData.goodsConsumNum)
    CfUtils.FillImage(self.ImgCurrencyIcon, currencyVo.photoPath)
    self.isPurchased = checkNumber(playerComponent.playerDojo.isBuyGrowthFund) == 1
    KTool.SetActive(self.Purchased, self.isPurchased)
    KTool.SetActive(self.UnPurchased, not self.isPurchased)
    UIEventProxy.Create(self.BtnBuy.gameObject).onPointerClick = function()
        if not self.isPurchased then--未购买的话发送购买请求
            local haveDiamondNum = GoodsUtils.GetThingNo(self.purchaseData.goodsConsum)
            if haveDiamondNum >= self.purchaseData.goodsConsumNum then
                GameUtils.SecondConfirm
                (
                        localize("确认花费_Num__Name_购买战略物资？",{_Num_ = self.purchaseData.goodsConsumNum, _Name_ = currencyVo.name}),
                        function()
                            GameUtils.Request(
                                    Interfaces.GrowthFundBuyGrowthFund,
                                    {  },
                                    function(request, response)
                                        if checkInt(response.errCode) == 0 then
                                            ---维护数据,刷新界面领取状态
                                            playerComponent.playerDojo.isBuyGrowthFund = 1
                                            --todo 维护本地可领取状态的服务端数据
                                            cs_coroutine.start(function() --数据维护完成后重新刷新UI
                                                coroutine.yield(self:MaintenanceData())
                                                GoodsUtils.ConsumeGoods({{goodsId = self.purchaseData.goodsConsum, num = self.purchaseData.goodsConsumNum}})
                                                self:FreshBaseUI()
                                                if self.isPurchased then
                                                    if isNull(self.purchasedEffectGo) then
                                                        self.purchasedEffectGo = CSPoolManager:GetNew(string.format("%s/UI_GrowthFundOpen.prefab", UIEffectParticlePath), true, 1)
                                                        KTool.SetParent(self.purchasedEffectGo, self.ParticleRoot.gameObject, false)
                                                    end
                                                end
                                            end)
                                        end
                                    end
                            )
                        end
                )
            else
                local StoreUtils = import('Game.UI.Store.StoreUtils')
                StoreUtils.OpenRechargePopUp(self.purchaseData.goodsConsumNum - haveDiamondNum)
            end
        end
    end
    if not self.LoopListView.IsListViewInit then
        self.LoopListView:InitListView(#self.rewardList, Bind(self, self.OnGetItemByIndex))
    else
        GameUtils.ReloadData(self.LoopListView, #self.rewardList)
    end

end

function GrowthFundDialog:OnGetItemByIndex(listView, index)
    if index < 0 then
        return nil
    end
    local cell = listView:NewListViewItem("Cell")
    local node = GetLuaBehaviour(cell.gameObject, "Game.UI.ResidentEvent.GrowthFundLevelRewardNode")
    if not cell.IsInitHandlerCalled then
        cell.IsInitHandlerCalled = true
        node:Init()
    end
    if not KTool.IsNull(node) then
        local luaIndex = index + 1
        local vo = self.rewardList[luaIndex]
        local getStatus = self.rewardDojo[checkString(vo.id)]
        local canGet = getStatus == Constants.GetStatus.Can
        --@region 刚进入列表时播放延时出现动画
        if not isNull(self["isAnimated"..luaIndex]) then
            if not self["isAnimated"..luaIndex] then
                self["isAnimated"..luaIndex] = true
                CfUtils.PlayDelayShowAnimate(node.transform:Find("Root"), luaIndex)
            else
                CfUtils.PlayDelayShowAnimate(node.transform:Find("Root"), 0)
            end
        else
            CfUtils.PlayDelayShowAnimate(node.transform:Find("Root"), 0)
        end
        --@endregion
        node.Env:FreshBaseUI(vo, getStatus, self.isPurchased)
        node.Env:SetCallBack(function() --点击回调
            if canGet then
                GameUtils.Request(
                        Interfaces.GrowthFundDrawRewards,
                        { rewardId = vo.id },
                        function(request, response)
                            if checkInt(response.errCode) == 0 then
                                ---维护数据,刷新界面领取状态
                                self:MaintenanceData({
                                    id = vo.id,
                                    status = Constants.GetStatus.Has
                                })--当前id数据改为已领取
                                GameUtils.SetRedPointNum(Constants.RedPointConst.GrowthFund, self:GetUnclaimedRewardCount())
                                node.Env:FreshGetStatus(Constants.GetStatus.Has)--刷新UI状态
                                local data = response.data
                                GoodsUtils.DrawRewards(data.rewards)--入包
                                --GameUtils.UpdateNavBarShowGoods({
                                --    Constants.Currency.HpId,
                                --    Constants.Currency.GoldId,
                                --    Constants.Currency.FreeDiamondId,
                                --})
                                UIModule.OpenDialog(
                                        {
                                            id = Constants.UITypeIds.UICommonRewardPop,
                                            parameters = { rewards = data.rewards }
                                        }
                                )
                            end
                        end
                )
            end
        end)
    end
    return cell
end

---维护奖励领取状态的方法，购买成功时不传参数，维护所有数据
---@param target table id：成长基金奖励表的id status:指定状态(Constants.GetStatus)
function GrowthFundDialog:MaintenanceData(target)
    if target then--领取了某个本地维护数据
        self.rewardDojo[checkString(target.id)] = target.status
        if self.isPurchased then
            playerComponent.playerDojo.paidPayLevelRewards[checkInt(target.id)] = checkString(target.id)
        end
        playerComponent.playerDojo.freePayLevelRewards[checkInt(target.id)] = checkString(target.id)
    else--购买解锁时维护所有数据
        for k, v in pairs(self.rewardDojo) do
            if v ~= Constants.GetStatus.Can then --不为可领取状态时，将所有满足条件的变为可领取
                if checkNumber(self.playerLevel) >= checkNumber(self.rewardVo[checkInt(k)].PlayerLv) then
                    self.rewardDojo[checkString(k)] = Constants.GetStatus.Can
                end
            end
        end
    end
end

function GrowthFundDialog:SortRewardData()
    local headList = {}
    local middleList = {}
    local tailList = {}
    for k, v in pairs(self.rewardVo) do
        local status = self.rewardDojo[checkString(v.id)]
        if status == Constants.GetStatus.Has then
            if table.keyof(playerComponent.playerDojo.paidPayLevelRewards, checkString(k)) ~= nil then--付费奖励领了才置底
                table.insert(tailList, v)
            else
                table.insert(headList, v)
            end
        elseif status == Constants.GetStatus.Can then
            table.insert(headList, v)
        elseif status == Constants.GetStatus.Not then
            table.insert(middleList, v)
        end
    end
    self.rewardList = {}
    for k, v in pairs(headList) do
        table.insert(self.rewardList, v)
    end
    for k, v in pairs(middleList) do
        table.insert(self.rewardList, v)
    end
    for k, v in pairs(tailList) do
        table.insert(self.rewardList, v)
    end
end

function GrowthFundDialog:GetUnclaimedRewardCount()
    local count = 0
    for k, v in pairs(self.rewardDojo) do
        if v == Constants.GetStatus.Can then
            count = count + 1
        end
    end
    return count
end

function GrowthFundDialog:OnDestroy()
    if not isNull(self.purchasedEffectGo) then
        CSPoolManager:GiveBack(self.purchasedEffectGo, 0)
        self.purchasedEffectGo = nil
    end
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
    self = nil --lua层的gc需要
end

return GrowthFundDialog